const query = $input.first().json.query || {};
const fileId = query.file_id || '';
const code = query.code || '';

if (!fileId || !code) {
  return [{ json: { valid: false, error: 'Parametres manquants (file_id ou code)' } }];
}

return [{ json: { valid: true, file_id: fileId, code: code } }];

const query = $('Extraire parametres').first().json;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const flashcards = JSON.parse(buffer.toString('utf-8'));

if (flashcards.code_suppression !== query.code) {
  return [{ json: { verified: false, error: 'Code invalide' } }];
}

const cartes = flashcards.cartes || [];
function diffColor(d) { return d === 'facile' ? '#16a34a' : d === 'moyen' ? '#d97706' : '#dc2626'; }

let cardsHtml = '';
for (const c of cartes) {
  cardsHtml += `<label style="display:block;border:1px solid #e2e8f0;border-radius:8px;padding:14px 16px;margin-bottom:10px;cursor:pointer">
    <div style="display:flex;align-items:flex-start;gap:12px">
      <input type="checkbox" name="cartes" value="${c.numero}" checked class="carte-checkbox" style="margin-top:4px;width:18px;height:18px;flex:0 0 auto">
      <div style="flex:1">
        <div style="color:${diffColor(c.difficulte)};font-size:11px;font-weight:bold;text-transform:uppercase;margin-bottom:4px">${c.difficulte || ''}</div>
        <div style="font-weight:bold;margin-bottom:4px">Q${c.numero} : ${c.question}</div>
        <div style="color:#475569;font-size:14px">${c.reponse}</div>
      </div>
    </div>
  </label>`;
}

const html = `<html>
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"></head>
<body style="font-family:sans-serif;background:#f8fafc;margin:0;padding:24px">
  <div style="max-width:640px;margin:0 auto">
    <h2 style="margin-bottom:4px">BOX &mdash; Choisissez les cartes a publier</h2>
    <p style="color:#64748b;margin-top:0">${flashcards.matiere} &mdash; ${flashcards.niveau} &mdash; ${flashcards.notion}</p>
    <div style="margin:16px 0">
      <button type="button" onclick="document.querySelectorAll('.carte-checkbox').forEach(c=>c.checked=true)" style="background:#e2e8f0;border:none;border-radius:6px;padding:8px 14px;margin-right:8px;cursor:pointer">Tout selectionner</button>
      <button type="button" onclick="document.querySelectorAll('.carte-checkbox').forEach(c=>c.checked=false)" style="background:#e2e8f0;border:none;border-radius:6px;padding:8px 14px;cursor:pointer">Tout deselectionner</button>
    </div>
    <form method="POST" action="https://n8n.srv868991.hstgr.cloud/webhook/box-select-confirm">
      <input type="hidden" name="file_id" value="${query.file_id}">
      <input type="hidden" name="code" value="${query.code}">
      ${cardsHtml}
      <button type="submit" style="background:#16a34a;color:white;border:none;border-radius:8px;padding:14px 32px;font-size:16px;font-weight:bold;cursor:pointer;width:100%;margin-top:8px">Publier la selection</button>
    </form>
    <p style="color:#94a3b8;font-size:12px;text-align:center;margin-top:16px">Decochez une carte pour l'exclure. Si vous decochez tout, rien ne sera publie.</p>
  </div>
</body>
</html>`;

return [{ json: { verified: true, html } }];

const body = $input.first().json.body || {};
const fileId = body.file_id || '';
const code = body.code || '';
let selected = body.cartes;
if (selected === undefined || selected === null || selected === '') selected = [];
if (!Array.isArray(selected)) selected = [selected];
selected = selected.map(n => parseInt(n, 10)).filter(n => !isNaN(n));

if (!fileId || !code) {
  return [{ json: { valid: false, error: 'Parametres manquants' } }];
}

return [{ json: { valid: true, file_id: fileId, code: code, selected: selected } }];

const query = $('Extraire parametres Confirmation').first().json;
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const flashcards = JSON.parse(buffer.toString('utf-8'));

if (flashcards.code_suppression !== query.code) {
  return [{ json: { verified: false, error: 'Code invalide' } }];
}

const allCartes = flashcards.cartes || [];
const selectedSet = new Set(query.selected);
const kept = allCartes.filter(c => selectedSet.has(c.numero));
const removedCount = allCartes.length - kept.length;

return [{ json: {
  verified: true,
  empty: kept.length === 0,
  file_id: query.file_id,
  code: query.code,
  id: flashcards.id,
  matiere: flashcards.matiere,
  niveau: flashcards.niveau,
  notion: flashcards.notion,
  prof_nom: flashcards.prof_nom,
  prof_email: flashcards.prof_email,
  date_creation: flashcards.date_creation,
  cartes_json: JSON.stringify({ ...flashcards, cartes: kept, nb_cartes: kept.length }),
  nb_cartes: kept.length,
  removed_count: removedCount
} }];

const setData = $('Verifier et filtrer').first().json;

let catalogue;
try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  let parsed = JSON.parse(buffer.toString('utf-8'));
  if (typeof parsed === 'string') parsed = JSON.parse(parsed);
  if (typeof parsed === 'object' && Array.isArray(parsed.sets)) {
    catalogue = parsed;
  } else {
    catalogue = { last_updated: '', total_sets: 0, sets: [] };
  }
} catch (e) {
  catalogue = { last_updated: '', total_sets: 0, sets: [] };
}

if (catalogue.sets.some(s => s.id === setData.id)) {
  return [{ json: { already_published: true, notion: setData.notion } }];
}

catalogue.sets.push({
  id: setData.id,
  matiere: setData.matiere,
  niveau: setData.niveau,
  notion: setData.notion,
  prof_nom: setData.prof_nom,
  nb_cartes: setData.nb_cartes,
  date_creation: setData.date_creation,
  drive_file_id: setData.file_id
});

catalogue.total_sets = catalogue.sets.length;
catalogue.last_updated = new Date().toISOString();

return [{ json: {
  catalogue_json: JSON.stringify(catalogue, null, 2),
  notion: setData.notion,
  already_published: false
} }];

const data = $('Verifier et filtrer').first().json;
const studentUrl = `https://ericduchateau.github.io/box/?set=${data.id}`;
const removedLine = data.removed_count > 0
  ? `<p style="color:#d97706;font-size:13px">${data.removed_count} carte(s) retiree(s) lors de votre relecture &mdash; ${data.nb_cartes} carte(s) publiee(s) au total.</p>`
  : '';

const emailHtml = `<div style="font-family:sans-serif;max-width:600px;margin:0 auto">
  <h2 style="color:#16a34a">&#9989; Vos fiches sont publiees et accessibles aux eleves !</h2>
  <p>
    <strong>Notion :</strong> ${data.notion}<br>
    <strong>Matiere :</strong> ${data.matiere} &mdash; ${data.niveau}<br>
    <strong>Nombre de fiches :</strong> ${data.nb_cartes}
  </p>
  ${removedLine}
  <hr>
  <h3>&#128279; Lien direct a partager avec vos eleves :</h3>
  <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:16px;margin:16px 0">
    <p style="margin:0 0 8px 0;font-size:13px;color:#64748b">Copiez ce lien dans votre cahier de texte numerique :</p>
    <p style="margin:0 0 12px 0;background:white;border:1px solid #dbeafe;border-radius:4px;padding:10px;font-family:monospace;word-break:break-all;font-size:14px;font-weight:bold">${studentUrl}</p>
    <a href="${studentUrl}" style="color:#2563eb;font-size:14px">Ouvrir les fiches &rarr;</a>
  </div>
  <p style="color:#64748b;font-size:12px">Ce lien ouvrira directement le jeu de fiches <strong>${data.notion}</strong> pour vos eleves, sans passer par le catalogue.</p>
</div>`;

return [{ json: { prof_email: data.prof_email, notion: data.notion, nb_cartes: data.nb_cartes, email_html: emailHtml } }];
